 WHERE kind IN ('device_offline','lease_survived_transport_failure')
 GROUP BY 1;

SELECT l.fence, d.fence_floor, l.state
  FROM farm.leases l JOIN farm.devices d ON d.id = l.device_id
 WHERE l.state IN ('held','suspect');

SELECT count(*) AS live_leases_below_floor
  FROM farm.leases l JOIN farm.devices d ON d.id = l.device_id
 WHERE l.state IN ('held','suspect') AND l.fence < d.fence_floor;

BEGIN;
UPDATE farm.leases SET state='released', released_at=now(),
       release_reason='device_offline'
 WHERE id = (SELECT id FROM farm.leases ORDER BY acquired_at DESC LIMIT 1);
ROLLBACK;

BEGIN;
SELECT id AS target FROM farm.leases ORDER BY acquired_at DESC LIMIT 1 \gset
SAVEPOINT b; UPDATE farm.leases SET fence = fence + 1 WHERE id = :'target';  ROLLBACK TO b;
SAVEPOINT c; UPDATE farm.leases SET expires_at = expires_at - interval '1 hour'
               WHERE id = :'target';                                         ROLLBACK TO c;
SAVEPOINT d; UPDATE farm.leases SET reclaimable_at = reclaimable_at - interval '1 hour'
               WHERE id = :'target';                                         ROLLBACK TO d;
SAVEPOINT e; UPDATE farm.leases SET state='held'
               WHERE id = (SELECT id FROM farm.leases WHERE state='released'
                            ORDER BY released_at DESC LIMIT 1);              ROLLBACK TO e;
ROLLBACK;

