BEGIN;
SET LOCAL ROLE farm_reaper;
SELECT current_user;
SELECT count(*) FROM farm.leases;          -- allowed
SELECT count(*) FROM farm.device_runtime;  -- must fail
ROLLBACK;

-- lease inserted with heartbeat_at 20 min ago, expires_at 5 min ago, ttl 15m / grace 30m
SELECT count(*) FROM farm.lease_mark_suspect(500);
SELECT * FROM farm.lease_renew(:lease, :fence, :holder_instance);

-- two leases inserted with heartbeat 50 min ago and reclaimable_at 5 min in the past;
-- one protected, one not; quiesce opened
SELECT protected, count(*) FROM farm.lease_mark_suspect(500) GROUP BY 1;
SELECT lease_id, old_fence, new_floor FROM farm.lease_reclaim(100, interval '35 seconds');

-- api stopped beating 25 minutes ago; reaper and scheduler look perfectly healthy
SELECT expires_at, reclaimable_at FROM farm.leases;
SELECT farm.reaper_arm(ARRAY['reaper','api','scheduler'], interval '60 seconds') AS refunded_gap;
SELECT expires_at, reclaimable_at FROM farm.leases;
SELECT component, ended_at - started_at AS outage FROM farm.control_plane_gap;
SELECT quiesce_until - now() AS reaper_quiet_for FROM farm.reaper_state;

SELECT farm.lease_witness(:lease, :fence, 12);   -- x2
SELECT witness_extensions FROM farm.leases WHERE id = :lease;
SELECT farm.lease_renew(:lease, :fence, :inst);
SELECT witness_extensions FROM farm.leases WHERE id = :lease;
-- then five calls with a cap of 3, then one at :fence - 1

UPDATE farm.reaper_state SET enabled = false, quiesce_until = now() + interval '1 hour';
SELECT count(*) AS max_runtime_ended FROM farm.lease_expire_max_runtime(100);
SELECT count(*) AS reclaim_ended     FROM farm.lease_reclaim(100, interval '35 seconds');

